"""Tests for pidiff archive handling and the rsync batch invocation in apply.py."""

import io
import subprocess
import tarfile
from pathlib import Path
from unittest.mock import patch

import pytest

from tsupdate import apply
from tsupdate.errors import TransientError, UpdateError

BATCH_NAME = "tsOS-base-arm64-update-2025.12.3-to-2025.12.4"

# Shape of a pidiff batch.sh: metadata variables followed by the script rsync
# --write-batch generates (options, --read-batch, ${1:-dest}, filter heredoc).
BATCH_SH = f"""#!/bin/sh
# generated by pidiff
set -e
BASE_IMAGE="tsOS-base-arm64-2025.12.3.img"
BASE_PRETTY_NAME="tsOS base 2025.12.3"
UPDATED_IMAGE='tsOS-base-arm64-2025.12.4.img'
UPDATED_PRETTY_NAME="tsOS base 2025.12.4"
echo "applying"
if [ -z "$1" ]; then exit 1; fi
rsync --filter=._- -aHAX --delete --numeric-ids --read-batch={BATCH_NAME} ${{1:-/media/root-up}} <<'#E#'
- /proc/
- /sys/
#E#
"""


def make_update_tar(tmp_path: Path, batch_sh: str = BATCH_SH, name: str = BATCH_NAME) -> Path:
    archive = tmp_path / f"{name}.tar"
    with tarfile.open(archive, "w") as tar:
        for member_name, data in (("batch.sh", batch_sh.encode()), (name, b"RSYNC-BATCH-BYTES")):
            info = tarfile.TarInfo(member_name)
            info.size = len(data)
            tar.addfile(info, io.BytesIO(data))
    return archive


class TestBatchSh:
    def test_parse_metadata(self, tmp_path):
        p = tmp_path / "batch.sh"
        p.write_text(BATCH_SH)
        meta = apply.parse_batch_metadata(p)
        assert meta == {
            "BASE_IMAGE": "tsOS-base-arm64-2025.12.3.img",
            "BASE_PRETTY_NAME": "tsOS base 2025.12.3",
            "UPDATED_IMAGE": "tsOS-base-arm64-2025.12.4.img",
            "UPDATED_PRETTY_NAME": "tsOS base 2025.12.4",
        }

    def test_extract_rsync_command(self, tmp_path):
        p = tmp_path / "batch.sh"
        p.write_text(BATCH_SH)
        options, filters = apply.extract_rsync_command_from_batch_sh(p)
        assert options == ["--filter=._-", "-aHAX", "--delete", "--numeric-ids"]
        assert filters == "- /proc/\n- /sys/\n"

    def test_extract_rsync_command_without_rsync_line(self, tmp_path):
        p = tmp_path / "batch.sh"
        p.write_text('BASE_PRETTY_NAME="x"\n')
        with pytest.raises(UpdateError, match="Could not find rsync command in batch.sh"):
            apply.extract_rsync_command_from_batch_sh(p)

    def test_missing_batch_sh(self, tmp_path):
        with pytest.raises(UpdateError, match="batch.sh not found"):
            apply.parse_batch_metadata(tmp_path / "batch.sh")
        with pytest.raises(UpdateError, match="batch.sh not found"):
            apply.extract_rsync_command_from_batch_sh(tmp_path / "batch.sh")


@pytest.fixture(autouse=True)
def extract_dir(tmp_path, monkeypatch):
    path = tmp_path / "data" / "extract"
    monkeypatch.setattr(apply, "EXTRACT_DIR", path)
    return path


class TestArchive:
    def test_extract_and_find_batch_file(self, tmp_path, extract_dir):
        archive = make_update_tar(tmp_path)
        extracted = apply.extract_update_archive(archive)
        assert extracted == extract_dir
        assert (extracted / "batch.sh").read_text() == BATCH_SH
        assert apply.find_rsync_batch_file(extracted, archive.name) == extracted / BATCH_NAME
        # Falls back to "any non-.sh file" when the archive was renamed
        assert apply.find_rsync_batch_file(extracted, "renamed.tar") == extracted / BATCH_NAME

    def test_extract_missing_file(self, tmp_path, extract_dir):
        with pytest.raises(UpdateError, match="Update file does not exist"):
            apply.extract_update_archive(tmp_path / "nope.tar")
        assert not extract_dir.exists()

    def test_corrupt_archive_does_not_leak_extract_dir(self, tmp_path, extract_dir):
        bad = tmp_path / "bad.tar"
        bad.write_bytes(b"this is not a tar archive")
        with pytest.raises(UpdateError, match="Could not extract archive"):
            apply.extract_update_archive(bad)
        assert not extract_dir.exists()

    def test_leftovers_are_wiped_before_extracting(self, tmp_path, extract_dir):
        extract_dir.mkdir(parents=True)
        (extract_dir / "stale").write_text("from an interrupted run")
        assert apply.extract_update_archive(make_update_tar(tmp_path)) == extract_dir
        assert not (extract_dir / "stale").exists()

    def test_member_escaping_the_directory_is_rejected(self, tmp_path, extract_dir):
        archive = tmp_path / "evil.tar"
        with tarfile.open(archive, "w") as tar:
            info = tarfile.TarInfo("../escaped.txt")
            data = b"x"
            info.size = len(data)
            tar.addfile(info, io.BytesIO(data))
        with pytest.raises(UpdateError, match="Could not extract archive"):
            apply.extract_update_archive(archive)
        assert not (extract_dir.parent / "escaped.txt").exists()
        assert not extract_dir.exists()


class TestVersionCompatibility:
    def test_match(self, tmp_path):
        p = tmp_path / "os-release"
        p.write_text('PRETTY_NAME="tsOS base 2025.12.3"\n')
        assert apply.check_version_compatibility("tsOS base 2025.12.3", p) == (True, "tsOS base 2025.12.3")

    def test_mismatch(self, tmp_path):
        p = tmp_path / "os-release"
        p.write_text('PRETTY_NAME="tsOS base 2025.12.1"\n')
        assert apply.check_version_compatibility("tsOS base 2025.12.3", p) == (False, "tsOS base 2025.12.1")

    def test_missing_os_release_is_allowed(self, tmp_path):
        # Documents current (fail-open) behaviour.
        assert apply.check_version_compatibility("tsOS base 2025.12.3", tmp_path / "missing") == (True, None)


class TestApplyRsyncBatch:
    def test_builds_command_and_feeds_filter_rules(self, tmp_path):
        batch = tmp_path / "batch"
        batch.write_bytes(b"x")
        target = tmp_path / "target"
        target.mkdir()
        with patch("subprocess.run", return_value=subprocess.CompletedProcess([], 0)) as run:
            rc = apply.apply_rsync_batch(batch, target, ["--filter=._-", "-a", "--itemize-changes"], "- /proc/\n", 0)
        assert rc == 0
        cmd = run.call_args.args[0]
        assert cmd == ["rsync", "--filter=._-", "-a", "--stats", f"--read-batch={batch}", str(target)]
        assert run.call_args.kwargs["input"] == b"- /proc/\n"
        assert run.call_args.kwargs["timeout"] is None  # 0 = unlimited

    def test_without_filter_uses_devnull_stdin(self, tmp_path):
        batch = tmp_path / "batch"
        batch.write_bytes(b"x")
        with patch("subprocess.run", return_value=subprocess.CompletedProcess([], 23)) as run:
            assert apply.apply_rsync_batch(batch, tmp_path, ["-a"], None) == 23
        assert run.call_args.kwargs["stdin"] is subprocess.DEVNULL
        assert run.call_args.kwargs["timeout"] == 3600.0

    def test_timeout_is_an_error_with_exit_code_124(self, tmp_path):
        batch = tmp_path / "batch"
        batch.write_bytes(b"x")
        with (
            patch("subprocess.run", side_effect=subprocess.TimeoutExpired("rsync", 5)),
            pytest.raises(UpdateError, match=r"Rsync timed out \(limit was 5s\); increase rsync_timeout") as exc,
        ):
            apply.apply_rsync_batch(batch, tmp_path, ["-a"], None, 5)
        assert exc.value.exit_code == 124
        assert not isinstance(exc.value, TransientError)  # it repeats until the limit is raised

    def test_missing_batch_or_target(self, tmp_path):
        with pytest.raises(UpdateError, match="Rsync batch file does not exist"):
            apply.apply_rsync_batch(tmp_path / "missing", tmp_path, ["-a"])
        batch = tmp_path / "batch"
        batch.write_bytes(b"x")
        with pytest.raises(UpdateError, match="Target directory does not exist"):
            apply.apply_rsync_batch(batch, tmp_path / "missing", ["-a"])

    def test_rsync_not_installed(self, tmp_path):
        batch = tmp_path / "batch"
        batch.write_bytes(b"x")
        with patch("subprocess.run", side_effect=FileNotFoundError), pytest.raises(UpdateError, match="not found: rsync"):
            apply.apply_rsync_batch(batch, tmp_path, ["-a"])

    @pytest.mark.parametrize("code", [0, 1, 23, 124, 99])
    def test_exit_code_messages(self, code):
        assert apply.handle_rsync_exit_code(code)


class TestExecuteApply:
    """End-to-end through execute_apply with mount/rsync faked."""

    @pytest.fixture
    def env(self, tmp_path, monkeypatch, booted_from):
        booted_from(2)
        monkeypatch.setattr(apply, "can_run_syncroot", lambda: True)
        target = tmp_path / "root-up"
        (target / "etc").mkdir(parents=True)
        (target / "etc" / "os-release").write_text('PRETTY_NAME="tsOS base 2025.12.3"\n')

        from contextlib import contextmanager

        mounts = []

        @contextmanager
        def fake_mount(device, mount_point):
            mounts.append(device)
            yield target

        monkeypatch.setattr(apply, "mount_context", fake_mount)
        return {"target": target, "mounts": mounts, "archive": make_update_tar(tmp_path)}

    def test_success(self, env):
        with patch("subprocess.run", return_value=subprocess.CompletedProcess([], 0)) as run:
            assert apply.execute_apply(str(env["archive"]), rsync_timeout_sec=0) == 0
        assert env["mounts"] == ["/dev/mmcblk0p3"]
        cmd = run.call_args.args[0]
        assert cmd[0] == "rsync"
        assert cmd[-1] == str(env["target"])
        assert cmd[-2].startswith("--read-batch=") and cmd[-2].endswith(BATCH_NAME)

    def test_version_mismatch_does_not_run_rsync(self, env):
        (env["target"] / "etc" / "os-release").write_text('PRETTY_NAME="tsOS base 2025.11.1"\n')
        with patch("subprocess.run") as run, pytest.raises(UpdateError, match="Version mismatch") as exc:
            apply.execute_apply(str(env["archive"]))
        assert exc.value.exit_code == 1
        run.assert_not_called()

    def test_rsync_failure_is_propagated(self, env):
        with patch("subprocess.run", return_value=subprocess.CompletedProcess([], 23)), pytest.raises(
            UpdateError, match="Rsync failed with exit code 23: Partial transfer"
        ) as exc:
            apply.execute_apply(str(env["archive"]))
        assert exc.value.exit_code == 23

    def test_refused_when_cannot_run(self, env, monkeypatch):
        monkeypatch.setattr(apply, "can_run_syncroot", lambda: False)
        with pytest.raises(UpdateError, match="can only be run when booted regularly"):
            apply.execute_apply(str(env["archive"]))
        assert env["mounts"] == []

    def test_download_failure_is_raised(self, env, monkeypatch):
        def offline(source, artifacts):
            raise TransientError("Cannot reach GitHub: down")

        monkeypatch.setattr(apply, "ensure_file", offline)
        with pytest.raises(TransientError, match="Cannot reach GitHub"):
            apply.execute_apply("https://github.com/trackIT-Systems/x/releases/download/v/u.tar")
        assert env["mounts"] == []


class TestApplyCleanup:
    """A downloaded update is deleted after a successful apply, but never a user-supplied file and
    never after a failure (so a retry doesn't have to download it again)."""

    @pytest.fixture
    def downloaded(self, tmp_path, monkeypatch, booted_from):
        from contextlib import contextmanager

        booted_from(2)
        monkeypatch.setattr(apply, "can_run_syncroot", lambda: True)
        target = tmp_path / "root-up"
        (target / "etc").mkdir(parents=True)
        (target / "etc" / "os-release").write_text('PRETTY_NAME="tsOS base 2025.12.3"\n')

        @contextmanager
        def fake_mount(device, mount_point):
            yield target

        monkeypatch.setattr(apply, "mount_context", fake_mount)
        archive = make_update_tar(tmp_path)
        result = {"is_local": False}
        monkeypatch.setattr(apply, "ensure_file", lambda source, artifacts: (archive, result["is_local"]))
        return archive, result

    def run(self, rc=0, **kw):
        with patch("subprocess.run", return_value=subprocess.CompletedProcess([], rc)):
            return apply.execute_apply("https://github.com/trackIT-Systems/x/releases/download/v/u.tar", **kw)

    def test_download_removed_after_success(self, downloaded):
        archive, _ = downloaded
        assert self.run() == 0
        assert not archive.exists()

    def test_keep_download(self, downloaded):
        archive, _ = downloaded
        assert self.run(keep_download=True) == 0
        assert archive.exists()

    def test_download_kept_after_failure(self, downloaded):
        archive, _ = downloaded
        with pytest.raises(UpdateError):
            self.run(rc=23)
        assert archive.exists()

    def test_local_file_is_never_deleted(self, downloaded):
        archive, result = downloaded
        result["is_local"] = True
        assert self.run() == 0
        assert archive.exists()
